	palette = palettes[settings.graphics.palette];

	translate(width / -2, height / -2);
	if (width > 1000 && height > 680) largeScreen = true;
	else largeScreen = false;

	push();
	switch (gameScene) {
		case "menu":
			drawMenuScene();
			break;
		case "levelSelect":
			drawLevelSelectScene();
			break;
		case "settings":
			drawGeneralSettingsScene();
			break;
		case "graphicsSettings":
