function drawButton(str, x, y, size, callback = null) {
	push();
	let buttonHeight;
	if (size === true) {
		textSize(96);
		buttonHeight = 96 + 18;
	} else if (size === false) {
		textSize(48);
		buttonHeight = 48 + 12;
	} else {
		textSize(size);
		if (size > 96) {
			buttonHeight = size * 1.15;
			size = true;
		} else {
			buttonHeight = size * 1.4;
			size = false;
		}
	}

	const buttonWidth = textWidth(str) + (size ? 24 : 16);
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > x - buttonWidth / 2 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < x + buttonWidth / 2 &&
		(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > y - buttonHeight / 2 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < y + buttonHeight / 2 &&
		callback != null) {
		stroke(60);
		fill(255 - palette[4][0], 255 - palette[4][1], 255 - palette[4][2], 255);
		if (mouseWasPressed) {
			callback();
		}
	} else if (callback == null) {
		stroke(60);
		fill(255 - palette[4][0], 255 - palette[4][1], 255 - palette[4][2], 255);
	} else {
		stroke(0);
		fill(255 - palette[4][0], 255 - palette[4][1], 255 - palette[4][2], 180);
	}
	strokeWeight(5);
	rectMode(CENTER);
	rect(x, y, buttonWidth, buttonHeight);
	textAlign(CENTER, CENTER);
	fill(palette[4]);
	noStroke();
	text(str, x - (size ? 2.5 : 1.25), y - (size ? 12 : 6));
	pop();
}

