	if (!isGameRunning()) return;

	worldL.draw(leftSelected, player.position);
	worldR.draw(!leftSelected, player.position);

	image(worldR.outImage, 0, 0, width, height);

	if (!isDev) {
		if (!settings.general.minimalUI || UIinterest > 0) {
			textAlign(LEFT, TOP);
			textSize(32);
