			for (const i of [-2, -1, 1, 0]) {
				if (i === 0) {
					fill(...palette[4], alpha);
				} else {
					fill(255 - palette[4][0], 255 - palette[4][1], 255 - palette[4][2], alpha);
				}

				text(currentLevelName, 32 + i, 32 + i);
				if (player.oKeys > 0)
					text("O keys: " + player.oKeys, 32 + i, 64 + i);
