class Body { // bace class for physics
	constructor() {
		this.position = createVector(0, 0, 0);
		this.speed = createVector(0, 0, 0);
		this.size = createVector(1, 1);
		this.quality = false;
		this.xKeys = 0;
		this.oKeys = 0;
	}

	update(world) {
		const blocks = world.blocks;

		this.position.add(this.speed);

		this.runKeyCollisions(world);

		const orignalYposition = this.position.y,
			orignalYspeed = this.speed.y;

		if (this.runFloorCollision(blocks)) return; // insure player is on ground

		this.runKeyCollisions(world);
		this.runWallCollision(blocks); // do wall collisions now that the player is safely on the surface

		// retry floor collisions now that the player is outside of any walls
		// otherwise a wall the player is inside with count as a floor
		this.position.y = orignalYposition;
		this.speed.y = orignalYspeed;
		if (this.runFloorCollision(blocks)) return; // insure player is on ground

		this.runStairsCollision(blocks);
	}

	runStairsCollision(blocks) {
		// find the altitude the player should be at to stand on near by stairs
		// then move the player up to that altitude
		const collisions = this.getBlockCollisions(blocks, this.position, true);

		for (const collision of collisions) {
			let progress;
			switch (collision[6]) {
				case 0:
					progress = this.position.x + this.size.x - collision[0];
					break;
				case 1:
					progress = collision[3] - (this.position.z - this.size.y);
					break;
				case 2:
					progress = collision[2] - (this.position.x - this.size.x);
					break;
				case 3:
					progress = this.position.z + this.size.y - collision[1];
					break;
			}
			const stairTop = ceil(this.position.y) - constrain(progress, 0, 1);
			if (stairTop < this.position.y) {
				this.position.y = stairTop;
				this.speed.y = min(0, this.speed.y);
			}
		}
	}

	runFloorCollision(blocks) {
		// find near by floor
		// find out the altitude the player must be at to stand on them
		// if that space is empty move the player there
		// check for goal blocks too
		if (this.position.y > 0) {
			this.position.y = 0;
			this.speed.y = min(0, this.speed.y);
			return;
		}

		const collisions = this.getBlockCollisions(blocks, this.position);
		let solutionHeight = this.position.y;
		let solutionIsGoal = false;
		for (const collision of collisions) {
			const distance = solutionHeight - collision[4];
			if (distance >= 0 && distance < 0.1) {
				solutionHeight = min(solutionHeight, collision[4]);
				if (collision[5]) {
					solutionIsGoal = true;
				}
			}
		}

		if (solutionHeight !== this.position.y) {
			this.position.y = solutionHeight;
			this.speed.y = min(0, this.speed.y);
			if (solutionIsGoal) {
				switchDivide(false, true);
				nextLevel();
				return true;
			}
		}

		return false;
	}

	runWallCollision(blocks, imaginary = false) {
		// find places to move the player to solve wall collisions
		// move the player to the closest
		// return distance moved
		const solutions = this.getWallCollisionIterativeSolutions(blocks, this.position, this.quality ? 2 : 1);
		let bestSolution = null;
		let bestSolutionDistance = Infinity;
		for (let i = 0; i < solutions.length; i++) {
			const distance = solutions[i].dist(this.position);
			if (distance < bestSolutionDistance) {
				bestSolution = solutions[i];
				bestSolutionDistance = distance;
			}
		}
		if (bestSolution != null) {
			if (!imaginary) {
				player.position = bestSolution;
			}
			return bestSolutionDistance;
		}
		return 0;
	}

	getWallCollisionIterativeSolutions(blocks, position, depthLeft = 0) {
		// find places to move the player on a collision
		// iteratively find new places for the old places the cause collisions
		// return all valid solutions

		const solutions = this.getWallCollisionSolutions(blocks, position);
		const badSolutions = [];
		for (let i = 0; i < solutions.length; i++) {
			if (this.getWallCollisionSolutions(blocks, solutions[i]).length > 0) {
				badSolutions.push(solutions.splice(i, 1)[0]);
				i--;
			}
		}
		if (depthLeft > 0) {
			const newSolutions = [];
			for (const badSolution of badSolutions) {
				newSolutions.push(...this.getWallCollisionIterativeSolutions(blocks, badSolution, depthLeft - 1));
			}
			solutions.push(...newSolutions);
		}
		return solutions;
	}

	getWallCollisionSolutions(blocks, position) {
		// find places to move the player on a collision
		const collisions = this.getBlockCollisions(blocks, position);
		const solutions = [];
		for (const collision of collisions) {
			const saftyValue = 0.000001;

			solutions.push(
				createVector(collision[0] - this.size.x - saftyValue, position.y, position.z),
				createVector(position.x, position.y, collision[1] - this.size.y - saftyValue),
				createVector(collision[2] + this.size.x + saftyValue, position.y, position.z),
				createVector(position.x, position.y, collision[3] + this.size.y + saftyValue));
		}
		return solutions;
	}

	runKeyCollisions(world, allowDoors = true) {
		const collisions = this.getBlockCollisions(world.blocks, this.position);

		for (const collision of collisions) {
			if (collision[7] !== "none") {
				let x = round(collision[0]);
				let y = round(collision[4] + 0.5);
				let z = round(collision[1]);
				if (this.interactKey(collision[7], allowDoors))
					world.deleteBlock(x, y, z);
				if (this.oKeys !== 0 || this.xKeys !== 0) UIinterest = 120;
			}
		}
	}

	interactKey(keyType, allowDoors = true) {
		switch (keyType) {
			case "oKey":
				this.oKeys++
				return true;
			case "xKey":
				this.xKeys++
				return true;
			case "oDoor":
				if (this.oKeys > 0 && allowDoors) {
					this.oKeys--;
					return true;
				}
				break;
			case "xDoor":
				if (this.xKeys > 0 && allowDoors) {
					this.xKeys--;
					return true;
				}
				break;
		}
		return false;
	}

	getBlockCollisions(blocks, position, stairsSort = false) {
		// find what blocks the player is touching on their current plane by...
		// finding all colliders in blocks the player intersects
		// narrowing to colliders the player intersects with vertically
		// rotating the colliders according to their parent blocks
		// narrowing to colliders the player intersects with horizontally

		// collider format is
		// [min X, min Y, max X, max Y, block top's altitude, is the top of the block a goal, block's integer rotation]
		const nearColliders = [];
		for (let x = round(position.x - this.size.x); x < round(position.x + this.size.x) + 1; x++) {
			for (let y = round(position.z - this.size.y); y < round(position.z + this.size.y) + 1; y++) {
				const blockKey = x + "," + ceil(position.y) + "," + y;
				if (blocks[blockKey] != null) {
					const type = blocks[blockKey].type;
					const colliders = blockProperties[type].colliders;
					const blockRotation = round(blocks[blockKey].r / HALF_PI);
					const blockTop = ceil(position.y) - blockProperties[type].height;
					const isStairs = blockProperties[type].isStairs;
					const isGoal = blockProperties[type].isGoal;
					const keyType = blockProperties[type].keyType; // "none", "xKey", "oKey"
					if (isStairs) { // sort out stairs and non-stairs
						if (stairsSort) {
							nearColliders.push([
								x - 0.5,
								y - 0.5,
								x + 0.5,
								y + 0.5,
								blockTop,
								isGoal,
								blockRotation,
								keyType
							]);
						}
					} else if (blockProperties[type].addTop && position.y - 0.1 < blockTop) {
						nearColliders.push([
							x - 0.5,
							y - 0.5,
							x + 0.5,
							y + 0.5,
							blockTop,
							isGoal,
							blockRotation,
							keyType
						]);
					} else if (blockTop < position.y) {
						for (let i = 0; i < colliders.length; i++) {
							let v = [
								colliders[i][0],
								colliders[i][1],
								colliders[i][0] + colliders[i][2],
								colliders[i][1] + colliders[i][3],
								blockTop,
								isGoal,
								blockRotation,
								keyType
							];
							switch (blockRotation) { // rotate collider
								case 1:
									v = [v[1], -v[2], v[3], -v[0], v[4], v[5], v[6], v[7]];
									break;
								case 2:
									v = [-v[2], -v[3], -v[0], -v[1], v[4], v[5], v[6], v[7]];
									break;
								case 3:
									v = [-v[3], v[0], -v[1], v[2], v[4], v[5], v[6], v[7]];
									break;
							}
							v[0] += x;
							v[1] += y;
							v[2] += x;
							v[3] += y;
							nearColliders.push(v);
						}
					}
				}
			}
		}
		const lowPosX = position.x - this.size.x;
		const highPosX = position.x + this.size.x;
		const lowPosY = position.z - this.size.y;
		const highPosY = position.z + this.size.y;
		const collisions = [];
		for (const nearCollider of nearColliders) {
			if (nearCollider[0] < highPosX &&
				nearCollider[2] > lowPosX &&
				nearCollider[1] < highPosY &&
				nearCollider[3] > lowPosY) {
				collisions.push(nearCollider);
			}
		}
		return collisions;
	}
}

class Box extends Body {
	constructor(size = 0.32) {
		this.quality = false;
		this.height = size * 2;
		this.size = createVector(size, size);
	}

	draw() {
		push();
		translate(this.position.x, this.position.y, this.position.z);
		translate(0, -this.height, 0);
		box(this.size.x * 2, this.height, this.size.y * 2);
		pop()
	}
}

class Character extends Body {
	constructor() {
		super();
		this.quality = true;
		this.size = createVector(0.16, 0.16);
		this.facing = createVector(0, 0); // direction of body
		this.lookFacing = createVector(0, 0); // direction of head
		this.walkTime = 0; // how long has the player been moving?
		this.walkingSpeed = 0.08;
	}

	reset(altitude) {
		this.oKeys = 0;
		this.xKeys = 0;
		this.resetPosition(altitude);
	}

	resetPosition(altitude = 0) {
		this.position.x = 0;
		this.position.y = -altitude;
		this.position.z = 0;
	}

	update(blocks) {
		this.lookFacing.x = noise(frameCount / 60) * 2.5 - 1.25;
		this.lookFacing.y = noise(frameCount / 60 + 5345) * 1.5 - 0.75;

		const moveVec = this.getMoveVec().mult(this.walkingSpeed);

		const horizontalSpeed = createVector(this.speed.x, this.speed.z);
		horizontalSpeed.add(moveVec);
		horizontalSpeed.mult(0.6);
		horizontalSpeed.limit(0.03);
		this.speed.x = horizontalSpeed.x;
		this.speed.z = horizontalSpeed.y;
		this.speed.y += 0.001;

		super.update(blocks);

		if (this.speed.mag() > 0.01) {
			this.walkTime++;
		} else {
			this.walkTime = 0;
		}
		this.facing.add(this.speed.x, this.speed.z);
		this.facing.limit(0.2);
	}

	draw() {
		push();
		translate(this.position.x, this.position.y, this.position.z);
		rotateX(this.speed.z * -5);
		rotateZ(this.speed.x * 5);
		scale(0.07);
		const angle = PI - this.facing.heading();
		rotateY(angle);
		fill(angle * 32, 255, 255)
		const frame = floor(this.walkTime / 5 + 4) % 12;
		if (this.walkTime > 0) {
			model(playerModels[frame]);
		} else {
			push();
			translate(0, -3.5, 0);
			box(1, 8, 3);
			pop();
		}
		translate(0, -9, 0);
		if (this.walkTime > 0) {
			translate(-playerBop.forward[frame], -playerBop.height[frame], 0);
		}
		rotateY(this.lookFacing.x);
		rotateZ(this.lookFacing.y);
		const lookAngle = PI - this.facing.copy().rotate(this.lookFacing.x).heading();
		fill(lookAngle * 32, 255, 255);
		box(1, 2, 3);
		pop();
	}

	getMoveVec() {
		let moveVec = createVector(0, 0);

		if (!editMode) {
			if (gamepadVector().mag() > 0) {
				moveVec = gamepadVector().normalize();
			} else if (settings.general.runMobile && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
				if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height / 3) {
					moveVec.add(0, -1);
				}
				if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > height / 3 * 2) {
					moveVec.add(0, 1);
				}
				if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width / 3) {
					moveVec.add(-1, 0);
				}
				if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width / 3 * 2) {
					moveVec.add(1, 0);
				}
				return moveVec.normalize();
			} else {
				if (keyIsDown(87) || keyIsDown(38)) {
					moveVec.add(0, -1);
				}
				if (keyIsDown(83) || keyIsDown(40)) {
					moveVec.add(0, 1);
				}
				if (keyIsDown(65) || keyIsDown(37)) {
					moveVec.add(-1, 0);
				}
				if (keyIsDown(68) || keyIsDown(39)) {
					moveVec.add(1, 0);
				}
				moveVec = moveVec.normalize();
			}
		}

		moveVec.rotate(cameraAngle);
		return moveVec;
	}
}

// === Tab: world.js ===
let levelsStoredLocally = false; // are levels in local storage or the gameData zip
let currentLevel = 0;
let levelCount; // total amount of levels found

// scene shader red channel is object rotation 
// blue is object lightness(window.color(monochrome colour))

class World {
	constructor(width, height, lightPaletteIndex, darkPaletteIndex) {
		this.blocks = {};

		this.darkPaletteIndex = darkPaletteIndex; // range of colours for the world
		this.lightPaletteIndex = lightPaletteIndex;
		this.backgroundLightness = 255; // where on the colour range is the background

		this.width = width;
		this.height = height;

		// remmeber old settings to detect changes
		this.doAA = settings.graphics.doAA;
		this.doAC = settings.graphics.doAC;
		this.doHQ = settings.graphics.doHQ;

		this.outImage = null;
		this.altWorld = null;
		this.staticModel = null;

		this.buildGraphics();
	}

	setLevel(level) {
		if (!level.blocks) return;
		this.setBlocks(level.blocks);
	}

	setBlocks(blocks) {
		this.blocks = blocks;
		this.staticModel = null;
	}

	deleteBlock(x, y, z) {
		const oldBlock = this.blocks[x + "," + y + "," + z];

		if (!oldBlock) return;
		delete this.blocks[x + "," + y + "," + z];

		if (!this.isStaticBlockType(oldBlock.type)) return;
		this.staticModel = null;
	}

	setBlock(x, y, z, type, r = 0) {
		const oldBlock = this.blocks[x + "," + y + "," + z];

		this.blocks[x + "," + y + "," + z] = {
			type,
			r
		};

		if (
			!this.isStaticBlockType(type) &&
			(!oldBlock || !this.isStaticBlockType(oldBlock.type))) return;

		this.staticModel = null;
	}

	getLevel() {
		return {
			blocks: this.blocks
		};
	}

	buildGraphics() {
		this.sceneBuf = createFramebuffer({
			width: this.width,
			height: this.height,
			depthFormat: UNSIGNED_INT,
			antialias: this.doAA
		});
		this.sceneShader = createShader(sceneVertShader, replaceShaderQualityParts(sceneFragShader, this.doHQ));
		this.postBuf = createFramebuffer({
			width: this.width,
			height: this.height,
			depth: false,
			antialias: this.doAA
		});
		this.postShader = createPostShader(this.doAC, this.doHQ);
		this.outImage = null;
	}

	removeGraphics() { // remove graphics objects to put the world in a like new state
		this.sceneBuf.remove();
		this.sceneBuf = null;
		this.sceneShader = null;
		this.postBuf.remove();
		this.postBuf = null;
		this.postShader = null;
	}

	rebuildGraphics() {
		this.removeGraphics();
		this.buildGraphics();
	}

	insureGraphics() { // make sure settings are up to date
		if (settings.graphics.doAA !== this.doAA ||
			settings.graphics.doAC !== this.doAC ||
			settings.graphics.doHQ !== this.doHQ) {
			this.doAA = settings.graphics.doAA;
			this.doAC = settings.graphics.doAC;
			this.doHQ = settings.graphics.doHQ;
			this.rebuildGraphics();
		}
	}

	resize(width, height) {
		this.width = width;
		this.height = height;
		this.rebuildGraphics();
	}

	draw(selected, cameraPosition) {
		this.insureGraphics();

		this.sceneBuf.begin();

		clear();
		background(255, 255, this.backgroundLightness);
		noStroke();
		ortho(-width / 2, width / 2, -height / 2, height / 2, 1, 10000);
		shader(this.sceneShader);
		this.sceneShader.setUniform("darkColor", palette[this.darkPaletteIndex].map(v => v / 255));
		this.sceneShader.setUniform("lightColor", palette[this.lightPaletteIndex].map(v => v / 255));
		this.sceneShader.setUniform("screenSize", [this.sceneBuf.width, this.sceneBuf.height]);
		// make the texture in the world move with the world not the camera
		const positionOffset = createVector(cameraPosition.x, cameraPosition.z).copy().rotate(-cameraAngle)
			.add(0, cameraPosition.y).mult(settings.general.sceneScale).mult(2, -sqrt(2));
		this.sceneShader.setUniform("positionOffset", [positionOffset.x, positionOffset.y]);

		translate(1, 1, -5000);
		rotateX(-PI / 4);
		rotateY(cameraAngle);
		scale(settings.general.sceneScale);
		translate(-cameraPosition.x, -cameraPosition.y, -cameraPosition.z);

		this.drawCachedBlocks();

		if (isDev) { // draw floor grid in level editor
			for (const blockID in this.blocks) { // draw level block shadows
				const block = this.blocks[blockID];
				const [x, _, z] = blockID.split(",");
				push();
				rotateX(HALF_PI);
				fill(0, 0, 96);
				translate(x, z, 0.02);
				plane(0.4, 0.4);
				fill(0, 0, 255);
				pop();
			}

			push();
			texture(devPlaneImage);
			rotateX(HALF_PI);
			plane(31, 31);
			if (selected && editMode) {
				fill(0);
				translate(devPlaceLocation.x, devPlaceLocation.z, 0.05);
				plane(0.4, 0.4);
				pop();
				push();
				translate(devPlaceLocation.x, devPlaceLocation.y, devPlaceLocation.z);
				rotateY(devPlaceLocation.r);
				fill((devPlaceLocation.r) * 32, 0, 128);
				model(blockModels[devPlaceSelect.value()]);
			}
			pop();
		}

		player.draw();
		this.sceneBuf.end();

		this.postBuf.begin();
		noStroke();
		shader(this.postShader);
		this.postShader.setUniform("sceneImage", this.sceneBuf);
		if (this.altWorld != null) {
			this.postShader.setUniform("altPostImage", this.altWorld.outImage);
		}
		this.postShader.setUniform("darkColor", palette[this.darkPaletteIndex].map(v => v / 255));
		this.postShader.setUniform("lightColor", palette[this.lightPaletteIndex].map(v => v / 255));
		this.postShader.setUniform("pixelSize", [1 / this.sceneBuf.width, 1 / this.sceneBuf.height]);
		this.postShader.setUniform("screenDivide", (this.altWorld != null) ? screenDivide : -1);
		this.postBuf._accessibleOutputs = { // worst hack ever
			grid: false,
			text: false
		}
		rect(0, 0, 1, 1);
		this.postBuf.end();

		this.outImage = this.postBuf;
	}

	drawBlocks() {
		this.drawStaticBlocks();
		this.drawDynamicBlocks();
	}

	drawCachedBlocks() {
		if (this.staticModel == null) {
			this.staticModel = buildGeometry(this.drawStaticBlocks.bind(this));
		}

		fill(0, 0, 255);
		model(this.staticModel);
		this.drawDynamicBlocks();
	}

	drawDynamicBlocks() {
		push();
		for (const blockID in this.blocks) { // draw level blocks
			const block = this.blocks[blockID];
			if (this.isStaticBlockType(block.type)) continue;

			const [x, y, z] = blockID.split(",");
			push();
			translate(x, y, z);
			rotateY(block.r);
			fill((block.r) * 32, 0, 255);
			model(blockModels[block.type]);
			pop();
		}
		pop();
	}

	drawStaticBlocks() {
		push();
		for (const blockID in this.blocks) { // draw level blocks
			const block = this.blocks[blockID];
			if (!this.isStaticBlockType(block.type)) continue;

			const [x, y, z] = blockID.split(",").map(Number);
			push();
			translate(x, y, z);
			rotateY(block.r);
			fill((block.r) * 32, 0, 255);
			push();
			model(blockModels[block.type]);
			pop();
			pop();
		}
		pop();
	}

	isStaticBlockType(type) {
		return !type.includes("Key") && !type.includes("Door");
	}
}

function setupLevels() {
	findLevelCount().then((_levelCount) => {
		levelCount = _levelCount;
		if (isDev) importToLocalLevels();
		if (levelCount <= 0 && currentLevel === 0) {
			if (isDev) { // create first level automaticly if the level editor is open
				logMessage("Creating first level for development");
				createLevelLocally();
			} else {
				logMessage("No levels found");
			}
		}
	});
}

function nextLevel() {
	if (currentLevel + 1 >= levelCount) {
		if (isDev) {
			logMessage("Next level missing");
		} else {
			gameScene = "winScreen";
		}
		return false;
	}
	currentLevel++;
	loadLevel(currentLevel);
	return true;
}

function previousLevel() {
	if (currentLevel <= 0) {
		logMessage("No previous level");
		return false;
	}
	currentLevel--;
	loadLevel(currentLevel);
	return true;
}

function loadLevel(levelNumber, fromLocalStorage = levelsStoredLocally) { // load a level then run the game after loading
	if (pauseReasons["loadingLevel"]) return;

	if (levelNumber >= levelCount) {
		logMessage("Can't load level that does not exist");
		return;
	}

	if (fromLocalStorage) {
		const levelData = JSON.parse(localStorage.getItem("levelData" + levelNumber));
		setLevelData(levelData, levelNumber);
	} else {
		pauseReasons["loadingLevel"] = true;

		gameData.getJSON(`levelData${levelNumber}.json`, (data) => {
			setLevelData(data, levelNumber);
			delete pauseReasons["loadingLevel"];
		});
	}

	localStorage.setItem("levelProgress", max(getLevelProgress(), currentLevel));
}

function getLevelProgress() {
	const progress = localStorage.getItem("levelProgress");
	if (progress == null) return 0;
	return progress;
}

function setLevelData(levelData, levelNumber) {
	currentLevel = levelNumber;
	worldL.setLevel(levelData.left);
	worldR.setLevel(levelData.right);
	player.reset(levelData.startingHeight);
	currentLevelName = levelData.name;

	if (isDev) {
		startingHeightInput.value(String(levelData.startingHeight));
		levelNameInput.value(levelData.name);
	}

	UIinterest = 160;
	cameraAngle = -Math.PI / 4;
}

function findLevelCount(fromLocalStorage = levelsStoredLocally) { // find the total amount of levels
	if (fromLocalStorage) {
		let levelNumber = 0;
		while (localStorage.getItem("levelData" + levelNumber) != null) {
			levelNumber++;
		}
		return Promise.resolve(levelNumber);
	} else {
		return new Promise((resolve) => {
			gameData.getJSON("levelCount.json", data => {
				resolve(data.count);
			});
		});
	}
}

function createLevelLocally(levelNumber = levelCount) {
	localStorage.setItem("levelData" + levelNumber, JSON.stringify({
		left: {
			blocks: {}
		},
		right: {
			blocks: {}
		},
		startingHeight: 0,
		name: "untitled"
	}));
	findLevelCount().then((_levelCount) => {
		levelCount = _levelCount;
		loadLevel(levelCount - 1);
	});
}

function removeLastLevelLocally() {
	const levelNumber = levelCount - 1;
	if (levelNumber === currentLevel) {
		if (!previousLevel()) {
			return;
		}
	}
	localStorage.removeItem("levelData" + levelNumber);
	findLevelCount().then((_levelCount) => {
		levelCount = _levelCount;
		loadLevel(levelCount - 1);
	});
}

function switchLevelsLocally(levelNumberA, levelNumberB) {
	const levelDataA = localStorage.getItem("levelData" + levelNumberA);
	const levelDataB = localStorage.getItem("levelData" + levelNumberB);
	localStorage.setItem("levelData" + levelNumberA, levelDataB);
	localStorage.setItem("levelData" + levelNumberB, levelDataA);
	if (levelNumberA === currentLevel || levelNumberB === currentLevel) {
		loadLevel(currentLevel);
	}
}

function importToLocalLevels() {
	if (levelsStoredLocally) return;
	let levelsLeft = levelCount;
	if (levelsLeft <= 0) {
		logMessage("No levels found to import");
	} else {
		pauseReasons["importingLevels"] = true;

		new Promise((resolve) => {
			for (let i = 0; i < levelCount; i++) {
				gameData.getJSON(`levelData${i}.json`, ((i, data) => {
					localStorage.setItem("levelData" + i, JSON.stringify(data));
					levelsLeft--;
					if (levelsLeft <= 0) resolve();
				}).bind(null, i));
			}
		}).then(() => {
			levelsStoredLocally = true;
			logMessage("Imported levels to local");
			delete pauseReasons["importingLevels"];
		});
	}
}

function saveCurrentLevelLocally(levelNumber = currentLevel) {
	localStorage.setItem("levelData" + levelNumber, JSON.stringify({
		left: worldL.getLevel(),
		right: worldR.getLevel(),
		startingHeight: Number(startingHeightInput.value() || 0),
		name: levelNameInput.value()
	}));
}

function saveLocalLevelsToZip() { // save to zip so it can be included in the gameData zip
	levelsZip = new JSZip();

	for (let i = 0; i < levelCount; i++) {
		const levelData = localStorage.getItem("levelData" + i);
		levelsZip.file(`levelData${i}.json`, levelData);
	}

	levelsZip.file("levelCount.json", JSON.stringify({
		count: levelCount
	}));

	levelsZip.generateAsync({
		type: "blob"
	}).then(function(blob) {
		downloadFile(blob, `levels${new Date().getTime()}.zip`);
	});
}

// === Tab: shaders.js ===
const sceneVertShader = `
precision mediump float;

attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
uniform mat3 uNormalMatrix;
uniform vec4 uMaterialColor;
uniform vec2 screenSize;

varying vec3 vNormal;
varying vec2 vPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);

	float r = uMaterialColor.r * 8.0;
	vNormal = aNormal * mat3(cos(r), 0, sin(r), 0, 1, 0, -sin(r), 0, cos(r));
	vPosition = (uProjectionMatrix * uModelViewMatrix * positionVec4).xy * screenSize;
	vPosition.y = 1.0 - vPosition.y;

  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}
`;

const sceneFragShader = `
precision mediump float;

varying vec3 vNormal;
varying vec2 vPosition;

uniform vec4 uMaterialColor;
uniform vec3 darkColor;
uniform vec3 lightColor;
uniform vec2 positionOffset;

const float advSamples = #sceneAdvSamples#;

float random(vec2 position) {
	return fract(sin(dot(position.xy, vec2(524.1412, 243.5633))) * 46232.0);
}

float randomB(vec2 position) {
	return fract(sin(dot(position.xy, vec2(235.1412, 754.5633))) * 85674.0);
}

float randomC(vec2 position) {
	return fract(sin(dot(position.xy, vec2(745.1412, 867.5633))) * 65782.0);
}

float subSample(vec2 sectorCoord, vec2 subSectorCoord, vec2 offset){
	sectorCoord = sectorCoord - offset;
	subSectorCoord = subSectorCoord + offset;
	float dist = distance(subSectorCoord, vec2(random(sectorCoord), randomB(sectorCoord)) + 0.5);
	if(dist < 0.5) {
		return randomC(sectorCoord);
	} else {
		return 0.0;
	}
}

float sample(vec2 position, float scale) {
	vec2 sectorCoord = floor(position / scale);
	vec2 subSectorCoord = fract(position / scale);

	return max(max(subSample(sectorCoord, subSectorCoord, vec2(0.0, 0.0)),
         subSample(sectorCoord, subSectorCoord, vec2(1.0, 0.0))),
         max(subSample(sectorCoord, subSectorCoord, vec2(0.0, 1.0)),
         subSample(sectorCoord, subSectorCoord, vec2(1.0, 1.0))));
}

float advSample(float light, vec2 position, float scale) {
	for(float i = 0.0; i < advSamples; i ++) {
		float s = sample(position + vec2(i * 23.0 + 54.0, i * -43.0 + 13.0), scale);
		if(s > clamp(light * (advSamples + 1.0 - i), 0.0, 1.0) ||
		s > clamp(light * (advSamples - i), 0.0, 1.0)) {
			float col = i / advSamples;
			return col;
		}
	}
	return 0.92;
}

void main() {
	float light = pow(clamp(1.3 - distance(vNormal, normalize(vec3(0.075, -0.275, 1.0))), 0.0, 1.0), 0.75);

	float depth = (gl_FragCoord.z) / 2.0 + 0.5;

	gl_FragColor = vec4(floor(depth * 256.0) / 256.0, mod(depth * 256.0, 1.0), uMaterialColor.b * advSample(light, vPosition + positionOffset, 10.0), uMaterialColor.a);
}
`;

const postVertShader = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;

  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  gl_Position = positionVec4;
}
`;

const postACfragShader = `
precision mediump float;

uniform sampler2D sceneImage;
uniform sampler2D altPostImage;
uniform vec3 darkColor;
uniform vec3 lightColor;
uniform vec2 pixelSize;
uniform float screenDivide;

varying vec2 vTexCoord;

float getDepth(vec4 col) {
	return col.r + col.g / 256.0;
}

float sample(float depth, vec2 coords, float accuracy) {
	vec4 col = texture2D(sceneImage, coords);
	float otherDepth = getDepth(col);
	return depth - otherDepth > accuracy ? 0.0035 : 0.0;
}

float sampleAC(float depth, vec2 coords, vec2 dist, float accuracy) {
	return sample(depth, coords + vec2(0.0, dist.y), accuracy) +
	sample(depth, coords + vec2(0.0, -dist.y), accuracy) +
	sample(depth, coords + vec2(dist.x, 0.0), accuracy) +
	sample(depth, coords + vec2(-dist.x, 0.0), accuracy) +
	sample(depth, coords + vec2(dist.x, dist.y), accuracy) +
	sample(depth, coords + vec2(dist.x, -dist.y), accuracy) +
	sample(depth, coords + vec2(-dist.x, dist.y), accuracy) +
	sample(depth, coords + vec2(-dist.x, -dist.y), accuracy);
}

bool nearEdge(vec2 coords) {
	return getDepth(texture2D(sceneImage, coords + vec2(0.0, pixelSize.y * 2.0))) > 0.999 ||
	getDepth(texture2D(sceneImage, coords + vec2(pixelSize.x * 2.0, 0.0))) > 0.999  ||
	getDepth(texture2D(sceneImage, coords + vec2(0.0, pixelSize.y * -2.0))) > 0.999 ||
	getDepth(texture2D(sceneImage, coords + vec2(pixelSize.x * -2.0, 0.0))) > 0.999;
}

void main() {
	vec2 coords = vTexCoord;

	#worldSwapStart#

	vec4 col = texture2D(sceneImage, coords);
	float depth = getDepth(col);

	if(depth > 0.999 || nearEdge(coords)) {
		gl_FragColor = vec4(mix(darkColor, lightColor, col.b), col.a);
	} else {
		float ac = #ACsample#;
		gl_FragColor = vec4(mix(darkColor, lightColor, col.b * ac), col.a);
	}

	#worldSwapEnd#
}
`;

const postFragShader = ` // no AC
precision mediump float;

uniform sampler2D sceneImage;
uniform sampler2D altPostImage;
uniform vec3 darkColor;
uniform vec3 lightColor;
uniform vec2 pixelSize;
uniform float screenDivide;

varying vec2 vTexCoord;

void main() {
	vec2 coords = vTexCoord;

	#worldSwapStart#

	vec4 col = texture2D(sceneImage, coords);
	gl_FragColor = vec4(mix(darkColor, lightColor, col.b), col.a);

	#worldSwapEnd#
}
`;

const hqShaderReplacments = {
	ACsample: "1.0 - (sampleAC(depth, coords, pixelSize * 16.0, 0.004) * 6.0 + sampleAC(depth, coords, pixelSize * 8.0, 0.002) * 8.0 + sampleAC(depth, coords, pixelSize * 4.0, 0.001) * 14.0 + sampleAC(depth, coords, pixelSize * 2.0, 0.0005) * 28.0)",
	sceneAdvSamples: "8.0"
}

const lqShaderReplacments = {
	ACsample: "1.0 - (sampleAC(depth, coords, pixelSize * 8.0, 0.002) * 16.0 + sampleAC(depth, coords, pixelSize * 3.0, 0.00075) * 40.0)",
	sceneAdvSamples: "4.0"
}

const worldSwitchShaderReplacment = {
	"worldSwapStart": `
		if(coords.x * 1.1 - coords.y * 0.1 > screenDivide) {
	`,
	"worldSwapEnd": `
		} else {
			gl_FragColor = texture2D(altPostImage, coords);
		}
	`
}

function createPostShader(doAC, doHQ) {
	const shaderString = replaceShaderParts(doAC ? postACfragShader : postFragShader, worldSwitchShaderReplacment);
	return createShader(postVertShader, replaceShaderQualityParts(shaderString, doHQ))
}

function replaceShaderQualityParts(shaderString, doHQ) { // replace for low and high quality shaders
	const replacments = doHQ ? hqShaderReplacments : lqShaderReplacments;
	return replaceShaderParts(shaderString, replacments)
}

function replaceShaderParts(shaderString, replacments) {
	// replace parts of shader code dynamically to apply graphics settings (and other stuff)
	for (let key in replacments) {
		shaderString = shaderString.replaceAll("#" + key + "#", replacments[key]);
	}
	return shaderString;
}

// === Tab: p5Zip.js ===
const DEFAULT_P5ZIP_CALLBACK = () => {};
const DEFAULT_P5ZIP__ERROR_CALLBACK = (error) => {
	throw error;
};

class p5Zip {
	constructor(url, subFolder = "") {
		this.zip = new Promise((resolve, reject) => {
			loadBytes(url, resolve, reject);
		}).then(({
			bytes
		}) => JSZip.loadAsync(bytes));

		if (subFolder != "") {
			this.zip = this.zip.then((zip) => zip.folder(subFolder));
		}
	}

	getJSON(path, callback = DEFAULT_P5ZIP_CALLBACK, errorCallback = DEFAULT_P5ZIP__ERROR_CALLBACK) {
		let obj = {};
		p5.instance._incrementPreload();

		this.zip.then((zip) => zip.file(path).async("string")).then((jsonString) => {
			const json = JSON.parse(jsonString);

			for (const key in json)
				obj[key] = json[key];

			callback(obj);
			p5.instance._decrementPreload();
		}).catch(errorCallback);

		return obj;
	}

	getModel(path, callback = DEFAULT_P5ZIP_CALLBACK, errorCallback = DEFAULT_P5ZIP__ERROR_CALLBACK) {
		const model = new p5.Geometry();
		model.gid = `${path}|false`;
		p5.instance._incrementPreload();

		this.zip.then((zip) => zip.file(path).async("base64")).then((base64) => {
			const dataURL = `data:text/plain;base64,${base64}`;

			p5.instance._decrementPreload();
			loadModel(dataURL, (urlModel) => {

				for (const key in urlModel)
					if (key != "gid")
						model[key] = urlModel[key];

				callback(model);
			}, errorCallback, path.slice(-4));
		}).catch(errorCallback);

		return model;
	}

	getImage(path, callback = DEFAULT_P5ZIP_CALLBACK, errorCallback = DEFAULT_P5ZIP__ERROR_CALLBACK) {
		const p5Img = new p5.Image(1, 1);
		p5.instance._incrementPreload();

		this.zip.then((zip) => zip.file(path).async("blob")).then((blob) => {
			const URL = window.URL ?? window.webkitURL;
			const rawImg = new Image();
			rawImg.src = URL.createObjectURL(blob);

			rawImg.onload = () => {
				p5Img.width = rawImg.width;
				p5Img.height = rawImg.height;
				p5Img.canvas.width = rawImg.width;
				p5Img.canvas.height = rawImg.height;

				p5Img.drawingContext.drawImage(rawImg, 0, 0);
				p5Img.modified = true;

				URL.revokeObjectURL(rawImg.src);

				callback(p5Img);
				p5.instance._decrementPreload();
			};

			rawImg.onerror = errorCallback;
		}).catch(errorCallback);

		return p5Img;
	}

	getFont(path, callback = DEFAULT_P5ZIP_CALLBACK, errorCallback = DEFAULT_P5ZIP__ERROR_CALLBACK) {
		const font = new p5.Font();
		p5.instance._incrementPreload();

		this.zip.then((zip) => zip.file(path).async("base64")).then((base64) => {
			const dataURL = `data:text/plain;base64,${base64}`;

			p5.instance._decrementPreload();
			loadFont(dataURL, (urlFont) => {

				for (const key in urlFont)
					font[key] = urlFont[key];

				callback(font);
			}, errorCallback, path.slice(-4));
		}).catch(errorCallback);

		return font;
	}
}

